	#include <alphatest_fragment>
	#include <alphahash_fragment>
	#include <roughnessmap_fragment>
vec3 nhPosition = vNHSurfacePosition * 0.01500000;
float nhBroad = nhSurfaceGrain(nhPosition, 18.0) * nhSurfaceBand(nhPosition, 36.54);
float nhDetailBand = nhSurfaceBand(nhPosition, 213.15000000);
float nhFine = nhSurfaceGrain(nhPosition, 105.00000000);
float nhWeave = nhSurfaceWave(nhPosition, vec3(0.97, 0.05, 0.24), 105.00000000, 0.0)
  * nhSurfaceWave(nhPosition, vec3(0.02, 0.99, 0.14), 95.55000000, 1.1);
float nhDetail = mix(nhFine, nhWeave, 0.00000000);
roughnessFactor = clamp(roughnessFactor + (nhBroad * 0.45 + nhDetail * nhDetailBand * 0.55)
  * 0.03300000, 0.045, 1.0);
diffuseColor.rgb *= 1.0 + (nhBroad * 0.7 + nhDetail * nhDetailBand * 0.3) * 0.01350000;
float nhRelief = nhDetail * 0.00460000;
	#include <metalnessmap_fragment>
	#include <normal_fragment_begin>
	#include <normal_fragment_maps>
normal = nhSurfaceNormal(-vViewPosition, normal, nhRelief, nhDetailBand);
	#include <clearcoat_normal_fragment_begin>
